mod solution;

fn main() {
    let cases = [
    (r#"[1,3,-1,-3,5,3,6,7]"#, r#"1,-1,-1,3,5,6"#),
    (r#"[2,1,4]"#, r#"2"#),
    (r#"
[2,1,4]
"#, r#"2"#),
    (r#"  
[1,3,-1,-3,5,3,6,7]
  "#, r#"1,-1,-1,3,5,6"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS dual-heap-window-median");
}
